    U.killChainBonus.textContent = `+${Math.round(killChainBonusTotal).toLocaleString()} SLAUGHTER THIS CHAIN`;
    U.killChainTime.textContent = active ? `${killChainT.toFixed(1)}s` : '0.0s';
