    let critCol = tier >= 4 ? '#ff74ef' : tier >= 3 ? '#72efff' : tier >= 2 ? '#ffe16d' : '#ffb35d',
      normalCol = tier >= 4 ? '#9df7ff' : tier >= 2 ? '#f5fbff' : col;
