      g.beginPath();
      g.arc(0, 0, 44, 0, Math.PI * 2);
      g.fill();
      g.strokeStyle = '#7552ff';
      g.lineWidth = 4;
      g.beginPath();
      g.arc(0, 0, 52, 0, Math.PI * 2);
      g.stroke();
      g.globalAlpha = 1;
