        if (h.t <= 0 && !h.fired) {
          h.fired = true;
          boom(h.x, G - 8, '#ffc45a', h.r, 1.1);
          if (pl.on && Math.abs(pl.x + pl.w / 2 - h.x) < h.r) hurt(Math.max(28, pl.max * 0.09), { x: h.x });
          h.dead = true;
        }
