      X.strokeStyle = 'rgba(7,10,16,.96)';
      X.lineWidth = 7;
      X.shadowBlur = 18;
      X.shadowColor = t.col;
      X.strokeText(t.s, t.x, t.y);
      X.fillStyle = t.col;
      X.fillText(t.s, t.x, t.y);
      X.font = '1000 18px system-ui';
