    d = d || weightedDefect((w.defects || []).map(x => x.id));
    if (!d) return w;
    w.defects = Array.isArray(w.defects) ? w.defects : [];
    if (w.defects.some(x => x.id === d.id)) return w;
    const severity = rankOf(w) === 0 ? 1.2 : 1;
    w.defects.push({ ...d, severity });
