      X.lineTo(-e.w * 0.35, -e.h * 0.52);
      X.moveTo(e.w * 0.22, -e.h * 0.34);
      X.lineTo(e.w * 0.35, -e.h * 0.52);
      X.stroke();
      X.strokeStyle = col;
